# Select a clear grasp candidate for purple_book to avoid collision with nearby obstacles
candidates = grasp_candidates("purple_book")

# Filter for candidates that fit and are clear of obstacles (prefer hand_clear)
best_candidate = None
for c in candidates:
    if c["fits_open_fingers"]:
        if c.get("hand_clear", False):
            best_candidate = c
            break

# If none are strictly hand_clear, choose the one across the long side (yaw = long_axis_yaw) or highest clearance
if best_candidate is None:
    for c in candidates:
        if c["fits_open_fingers"] and "long side" in c.get("source", ""):
            best_candidate = c
            break

if best_candidate is None:
    best_candidate = candidates[0]

# Ensure grasp height is near top of book
best_candidate["height"] = max(best_candidate.get("height", 0.025), 0.025)

res = grasp(best_candidate)
if res["holding_something"]:
    obs = observe()
    zone = obs["zones"]["orange_tray"]
    place_in_zone(zone, carry_clearance=0.18, retreat_dz=0.12)
    check("purple_book", "orange_tray")
